/**
 * frontend/src/components/Dashboard.jsx
 * Version Avancée - Optimisée et Améliorée
 */

import React, { useState, useEffect } from 'react';
import { attendanceAPI, studentsAPI } from './api_service';

const COLORS = {
  primary: '#4F46E5',
  primaryLight: '#EEF2FF',
  success: '#10B981',
  successLight: '#DCFCE7',
  danger: '#EF4444',
  dangerLight: '#FEE2E2',
  warning: '#F59E0B',
  warningLight: '#FEF3C7',
  textMain: '#1E293B',
  textMuted: '#64748B',
  border: '#E2E8F0',
  background: '#F8FAFC',
  surface: '#FFFFFF'
};

const Dashboard = ({ addNotification }) => {
  const [stats, setStats] = useState({
    active_students: 0,
    present_today: 0,
    absent_today: 0,
    summary: {
      unique_students: 0,
      total_records: 0,
      avg_confidence: 0,
      max_confidence: 0,
      min_confidence: 0
    }
  });

  const [attendanceLog, setAttendanceLog] = useState([]);
  const [statusList, setStatusList] = useState([]);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [error, setError] = useState(null);
  const [lastUpdated, setLastUpdated] = useState(null);
  const [refreshMessage, setRefreshMessage] = useState("");
  const [showAll, setShowAll] = useState(false);

  // ====================== CHARGEMENT DES DONNÉES ======================
  const loadData = async () => {
    try {
      setError(null);
      setLoading(true);

      const [studentStatsRes, attendanceStatsRes, logRes, statusRes] = await Promise.all([
        studentsAPI.getStats(),
        attendanceAPI.getStats(),
        attendanceAPI.getTodayLog(),
        attendanceAPI.getStatus()
      ]);

      if (!studentStatsRes?.success) throw new Error(studentStatsRes?.error || "Impossible de charger les statistiques étudiants");
      if (!attendanceStatsRes?.success) throw new Error(attendanceStatsRes?.error || "Impossible de charger les statistiques de présence");
      if (!logRes?.success) throw new Error(logRes?.error || "Impossible de charger le journal des présences");
      if (!statusRes?.success) throw new Error(statusRes?.error || "Impossible de charger le statut des étudiants");

      const sData = studentStatsRes.data || {};
      const active = Number(sData.active_students) || 0;

      const logs = Array.isArray(logRes.data?.records) ? logRes.data.records : [];
      const presentToday = new Set(logs.map(r => r.student_id || r.id)).size;

      setStats({
        active_students: active,
        present_today: presentToday,
        absent_today: Math.max(0, active - presentToday),
        summary: attendanceStatsRes.data || {}
      });

      setAttendanceLog(logs);
      setStatusList(Array.isArray(statusRes.data?.students) ? statusRes.data.students : []);

      setLastUpdated(new Date().toLocaleTimeString('fr-FR', {
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit'
      }));

      setLoading(false);
    } catch (err) {
      setLoading(false);
      const errorMessage = err.message || 'Erreur de connexion au serveur';
      setError(errorMessage);
      if (addNotification) {
        addNotification('Erreur lors du chargement du dashboard', 'error');
      }
    }
  };

  // ====================== REFRESH ======================
  const handleRefresh = () => {
    setRefreshing(true);
    setError(null);
    setRefreshMessage("⏳ Rafraîchissement en cours...");
    setTimeout(async () => {
      await loadData();
      setRefreshing(false);
      setRefreshMessage("");
    }, 2000);
  };

  // ====================== CHARGEMENT INITIAL ======================
  useEffect(() => {
    loadData();
  }, []);

  // ====================== RENDU CONDITIONNEL ======================
  if (loading) {
    return <div style={styles.loading}>Chargement en cours...</div>;
  }

  if (error) {
    return (
      <div style={styles.container}>
        <div style={styles.errorCard}>
          <h3 style={styles.errorTitle}>Erreur de synchronisation</h3>
          <p style={styles.errorText}>{error}</p>
          <p style={styles.errorHint}>
            Vérifiez que le backend est en cours d'exécution et que tous les endpoints sont accessibles.
          </p>
          <button 
            onClick={handleRefresh} 
            style={styles.retryBtn} 
            disabled={refreshing}
          >
            {refreshing ? 'Rafraîchissement...' : 'Réessayer'}
          </button>
        </div>
      </div>
    );
  }
    return (
    <div style={styles.container}>
      {/* HEADER */}
      <div style={styles.header}>
        <div>
          <h2 style={styles.title}>Tableau de Bord</h2>
          <p style={styles.subtitle}>
            Suivi des présences en temps réel • Dernière mise à jour : {lastUpdated || '—'}
          </p>
        </div>
        <button 
          onClick={handleRefresh} 
          style={styles.refreshBtn} 
          disabled={refreshing}
          aria-label="Actualiser le tableau de bord"
        >
          {refreshing ? 'Actualisation...' : 'Actualiser'}
        </button>
      </div>

      {refreshMessage && (
        <div style={styles.refreshMessage}>{refreshMessage}</div>
      )}

      {/* CARTES DE STATISTIQUES */}
      <div style={styles.statsGrid}>
        <StatCard label="Étudiants inscrits" value={stats.active_students} color={COLORS.primary} bgColor={COLORS.primaryLight} />
        <StatCard label="Présents aujourd'hui" value={stats.present_today} color={COLORS.success} bgColor={COLORS.successLight} />
        <StatCard label="Absents aujourd'hui" value={stats.absent_today} color={COLORS.danger} bgColor={COLORS.dangerLight} />
        <StatCard 
          label="Taux de présence" 
          value={stats.active_students > 0 ? `${((stats.present_today / stats.active_students) * 100).toFixed(1)}%` : 'N/A'} 
          color={
            stats.active_students > 0 && (stats.present_today / stats.active_students) >= 0.8 
              ? COLORS.success 
              : (stats.present_today / stats.active_students) < 0.5 
                ? COLORS.danger 
                : COLORS.warning
          } 
          bgColor={COLORS.warningLight}
        />
      </div>

      <div style={styles.mainGrid}>
        {/* Derniers scans */}
        <div style={styles.section}>
          <h3 style={styles.sectionTitle}>Derniers scans aujourd’hui</h3>
          {attendanceLog.length === 0 ? (
            <div style={styles.emptyState}>Aucune présence enregistrée aujourd’hui.</div>
          ) : (
            <div role="table" style={styles.table} aria-label="Derniers scans">
              <div style={styles.tableHeader}>
                <div style={{ flex: 2 }}>Étudiant</div>
                <div style={{ flex: 1 }}>Confiance</div>
                <div style={{ flex: 1 }}>Heure</div>
              </div>
              {attendanceLog.slice(0, showAll ? attendanceLog.length : 10).map((record, index) => (
                <div key={index} style={styles.tableRow}>
                  <div style={{ flex: 2, fontWeight: 500 }}>{record.student || record.name || 'Inconnu'}</div>
                  <div style={{ flex: 1 }}><ConfidenceBadge confidence={record.confidence} /></div>
                  <div style={{ flex: 1, color: COLORS.textMuted }}>
                    {record.timestamp ? new Date(record.timestamp).toLocaleTimeString('fr-FR', { hour: '2-digit', minute: '2-digit' }) : '—'}
                  </div>
                </div>
              ))}
            </div>
          )}
          <p style={styles.tableInfo}>Total aujourd’hui : {attendanceLog.length} scans</p>
          {attendanceLog.length > 10 && (
            <button onClick={() => setShowAll(!showAll)} style={styles.refreshBtn}>
              {showAll ? "Voir moins" : "Voir plus"}
            </button>
          )}
        </div>

        {/* Analyse du pipeline */}
        <div style={styles.section}>
          <h3 style={styles.sectionTitle}>Analyse du pipeline</h3>
          <div style={styles.summaryBox}>
            <SummaryItem label="Total scans aujourd’hui" value={stats.summary?.total_records || 0} color={COLORS.primary} />
            <SummaryItem label="Précision moyenne" value={stats.summary?.avg_confidence ? `${(stats.summary.avg_confidence * 100).toFixed(1)}%` : 'N/A'} color={COLORS.success} />
            <SummaryItem label="Meilleure précision" value={stats.summary?.max_confidence ? `${(stats.summary.max_confidence * 100).toFixed(1)}%` : 'N/A'} color={COLORS.success} />
            <SummaryItem label="Précision minimale" value={stats.summary?.min_confidence ? `${(stats.summary.min_confidence * 100).toFixed(1)}%` : 'N/A'} color={COLORS.danger} />
          </div>
        </div>
      </div>

      {/* Liste complète des étudiants */}
      <div style={styles.section}>
        <h3 style={styles.sectionTitle}>Liste des étudiants</h3>
        {statusList.length === 0 ? (
          <div style={styles.emptyState}>Aucun étudiant trouvé.</div>
        ) : (
          <div role="table" style={styles.table} aria-label="Liste des étudiants">
            <div style={styles.tableHeader}>
              <div style={{ flex: 2 }}>Nom</div>
              <div style={{ flex: 2 }}>Email</div>
              <div style={{ flex: 1 }}>Statut</div>
            </div>
            {statusList.map((student, index) => (
              <div key={index} style={styles.tableRow}>
                <div style={{ flex: 2, fontWeight: 500 }}>{student.name || 'Inconnu'}</div>
                <div style={{ flex: 2, color: COLORS.textMuted, fontSize: '0.9rem' }}>{student.email || '—'}</div>
                <div style={{ flex: 1 }}><StatusBadge present={student.present} /></div>
              </div>
            ))}
          </div>
        )}
        <p style={styles.tableInfo}>
          Total : {statusList.length} étudiants • {statusList.filter(s => s.present).length} présents
        </p>
      </div>
    </div>
  );
};

// ==================== SOUS-COMPOSANTS ====================
const StatCard = ({ label, value, color, bgColor }) => (
  <div style={{ ...styles.statCard, borderLeft: `5px solid ${color}` }}>
    <div style={{ ...styles.statIconWrapper, backgroundColor: bgColor }} />
    <div style={styles.statContent}>
      <p style={styles.statLabel}>{label}</p>
      <p style={{ ...styles.statValue, color }}>{value}</p>
    </div>
  </div>
);

const ConfidenceBadge = ({ confidence }) => {
  const score = Number(confidence) || 0;
  const percentage = (score * 100).toFixed(0);
  let color = COLORS.danger;
  let bg = COLORS.dangerLight;

  if (score > 0.7) { color = COLORS.success; bg = COLORS.successLight; }
  else if (score > 0.4) { color = COLORS.warning; bg = COLORS.warningLight; }

  return (
    <span style={{
      padding: '4px 10px',
      backgroundColor: bg,
      color,
      borderRadius: '6px',
      fontSize: '0.8rem',
      fontWeight: 700
    }}>
      {percentage}%
    </span>
  );
};

const StatusBadge = ({ present }) => (
  <span style={{
    padding: '6px 14px',
    backgroundColor: present ? COLORS.successLight : COLORS.dangerLight,
    color: present ? '#166534' : '#991B1B',
    borderRadius: '6px',
    fontSize: '0.85rem',
    fontWeight: 700
  }}>
    {present ? 'PRÉSENT' : 'ABSENT'}
  </span>
);

const SummaryItem = ({ label, value, color }) => (
  <div style={styles.summaryItem}>
    <p style={styles.summaryLabel}>{label}</p>
    <p style={{ ...styles.summaryValue, color }}>{value}</p>
  </div>
);

// ==================== STYLES ====================
const styles = {
  container: { padding: '30px', maxWidth: '1250px', margin: '0 auto', backgroundColor: COLORS.background },
  header: { display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '32px' },
  title: { margin: 0, fontSize: '2.1rem', fontWeight: 800, color: COLORS.textMain },
  subtitle: { margin: '6px 0 0 0', color: COLORS.textMuted },
  refreshBtn: { padding: '12px 24px', backgroundColor: COLORS.primary, color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 600 },
    refreshMessage: { 
    padding: '12px 20px',
    backgroundColor: COLORS.primaryLight,
    color: COLORS.primary,
    borderRadius: '8px',
    marginBottom: '20px',
    textAlign: 'center',
    fontWeight: 500
  },
  statsGrid: { 
    display: 'grid', 
    gridTemplateColumns: 'repeat(auto-fit, minmax(240px, 1fr))', 
    gap: '20px', 
    marginBottom: '32px' 
  },
  statCard: { 
    padding: '24px', 
    backgroundColor: COLORS.surface, 
    borderRadius: '12px', 
    boxShadow: '0 4px 12px rgba(0,0,0,0.05)', 
    display: 'flex', 
    alignItems: 'center', 
    gap: '16px' 
  },
  statIconWrapper: { 
    width: '48px', 
    height: '48px', 
    borderRadius: '10px', 
    display: 'flex', 
    alignItems: 'center', 
    justifyContent: 'center', 
    fontSize: '1.5rem' 
  },
  statContent: { flex: 1 },
  statLabel: { margin: 0, fontSize: '0.8rem', color: COLORS.textMuted, fontWeight: 600, textTransform: 'uppercase' },
  statValue: { margin: '4px 0 0 0', fontSize: '1.75rem', fontWeight: 800 },
  mainGrid: { display: 'grid', gridTemplateColumns: '2fr 1fr', gap: '24px', marginBottom: '30px' },
  section: { backgroundColor: COLORS.surface, borderRadius: '14px', padding: '24px', boxShadow: '0 4px 15px rgba(0,0,0,0.04)' },
  sectionTitle: { margin: '0 0 20px 0', fontSize: '1.15rem', fontWeight: 700, color: COLORS.textMain },
  table: { width: '100%' },
  tableHeader: { display: 'flex', padding: '12px 0', borderBottom: `2px solid ${COLORS.border}`, color: COLORS.textMuted, fontWeight: 600, fontSize: '0.9rem' },
  tableRow: { display: 'flex', padding: '14px 0', borderBottom: `1px solid ${COLORS.border}`, alignItems: 'center' },
  tableInfo: { marginTop: '12px', textAlign: 'right', fontSize: '0.85rem', color: COLORS.textMuted },
  summaryBox: { display: 'flex', flexDirection: 'column', gap: '16px' },
  summaryItem: { padding: '16px', backgroundColor: COLORS.background, borderRadius: '10px' },
  summaryLabel: { margin: 0, fontSize: '0.85rem', color: COLORS.textMuted },
