  emptyState: { padding: '50px 20px', textAlign: 'center', color: COLORS.textMuted, fontStyle: 'italic' },
  errorCard: { padding: '50px 30px', textAlign: 'center', backgroundColor: COLORS.dangerLight, borderRadius: '12px', border: `2px solid ${COLORS.danger}` },
  errorTitle: { color: COLORS.danger, marginBottom: '12px' },
  errorText: { color: '#991B1B', marginBottom: '16px' },
